python3 -c "
import zipfile, xml.etree.ElementTree as ET
z = zipfile.ZipFile('budget.xlsx')
print('archive:', z.namelist())
def local(tag): return tag.split('}')[-1]
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.iter():
        if local(si.tag) == 'si':
            shared.append(''.join(t.text or '' for t in si.iter() if local(t.tag) == 't'))
print('shared:', shared)
for name in z.namelist():
    if name.startswith('xl/worksheets/sheet'):
        print('===', name, '===')
        root = ET.fromstring(z.read(name))
        for row in root.iter():
            if local(row.tag) != 'row': continue
            cells = []
            for c in row:
                t = c.get('t'); v = None
                for child in c:
                    if local(child.tag) == 'v': v = child
                val = ''
                if v is not None and v.text is not None:
                    val = v.text
                    if t == 's': val = shared[int(val)]
                cells.append(c.get('r') + '=' + repr(val))
            print(' | '.join(cells))
"
